def eval_rpn(tokens):
    """
    Evaluates an arithmetic expression in Reverse Polish Notation.

    Args:
        tokens (list[str]): A list of string tokens (numbers and operators).

    Returns:
        int: The integer result of the evaluation.
    """
    stack = []
    operators = {'+', '-', '*', '/'}

    for token in tokens:
        if token in operators:
            if len(stack) < 2:
                raise ValueError("Invalid RPN expression: Not enough operands for operator.")

            # In RPN, the second popped operand is the right operand (op2)
            # and the first is the left operand (op1)
            operand2 = stack.pop()
            operand1 = stack.pop()

            if token == '+':
                result = operand1 + operand2
            elif token == '-':
                result = operand1 - operand2
            elif token == '*':
                result = operand1 * operand2
            elif token == '/':
                # Division truncates toward zero. We perform float division and then cast to int.
                # int() in Python truncates toward zero (e.g., int(2.5) is 2, int(-2.5) is -2).
                result = int(operand1 / operand2)

            stack.append(result)
        else:
            # Token is a number
            try:
                # We store numbers as floats to maintain precision during calculations
                stack.append(float(token))
            except ValueError:
                raise ValueError(f"Invalid token encountered: {token}")

    if len(stack) != 1:
        raise ValueError("Invalid RPN expression: Expression is malformed.")

    # The final result is guaranteed to be an integer after the operations.
    # We cast it to int to satisfy the return type requirement.
    return int(stack[0])
